def is_number(s):
    i, n = 0, len(s)
    if i < n and s[i] in '+-':
        i += 1
    digits = 0
    while i < n and s[i].isdigit():
        i += 1; digits += 1
    if i < n and s[i] == '.':
        i += 1
        while i < n and s[i].isdigit():
            i += 1; digits += 1
    if digits == 0:
        return False
    if i < n and s[i] in 'eE':
        i += 1
        if i < n and s[i] in '+-':
            i += 1
        exp = 0
        while i < n and s[i].isdigit():
            i += 1; exp += 1
        if exp == 0:
            return False
    return i == n
